# -----------------------------------------------------------------------------
# Text repository.
# ES: Repositorio de textos.
#
# Every user-facing report string assembled at runtime lives here, keyed by
# (section, key), written in English inside jamovi's `.()` so the jamovi
# compiler extracts it into the same catalog as the interface text
# (jamovi/i18n/es.po). Report text follows jamovi's own language; there is no
# language option (ARCHITECTURE.md §12). Variable parts are %s / %d
# placeholders filled with sprintf() after translation.
#
# ES: Todo texto del informe que se arma en tiempo de ejecución vive aquí,
# indexado por (sección, clave), escrito en inglés dentro de `.()` de jamovi
# para que el compilador lo extraiga al mismo catálogo que el texto de la
# interfaz (jamovi/i18n/es.po). El texto sigue el idioma de jamovi; no hay
# opción de idioma (ARCHITECTURE.md §12). Las partes variables son
# marcadores %s / %d que se llenan con sprintf() después de traducir.
#
# Writing rule: every interpretation answers four questions (what happened,
# why, what it means, what the researcher should do now). Never write a
# bracketed reference number; append "see references" after an author-year
# mention (CODE_STYLE.md §21).
#
# ES: Regla de redacción: cada interpretación responde cuatro preguntas (qué
# ocurrió, por qué, qué significa, qué hacer ahora). Nunca escribir un
# número de referencia entre corchetes; agregar "see references" después de
# una mención autor-año (CODE_STYLE.md §21).
# -----------------------------------------------------------------------------

.pl_text_table <- function(.) {
    list(

        # Introduction, shown while the model is not complete.
        # ES: Introducción, visible mientras el modelo no está completo.
        intro = list(
            what = .("PLS-SEM estimates relationships between constructs (concepts measured by several indicators) and how well each construct is measured. It builds each construct as a weighted combination of its indicators and is oriented to explaining and predicting the outcomes of the model."),
            step1 = .("Define each construct in Reflective Constructs or Formative Constructs: give it a name and drag its indicators into it. Reflective: the construct causes its indicators, which should correlate highly. Formative: the indicators together form the construct and need not correlate."),
            step2 = .("Open Structural Model: every construct has a row. Drag into a construct's row the constructs that predict it. A construct whose row stays empty is exogenous (only a predictor)."),
            step3 = .("The model is checked before estimation; if something is missing or inconsistent, the message names the construct or indicator at fault."),
            need_constructs = .("Define at least two constructs, each with at least one indicator."),
            need_paths = .("Add the structural model: drag at least one predictor into the row of a construct.")
        ),

        # Category A messages (jmvcore::reject).
        # ES: Mensajes de Categoría A (jmvcore::reject).
        errors = list(
            no_name = .("Every construct needs a name: one of the constructs has indicators but an empty name."),
            duplicated = .("The name '%s' is used for more than one construct. Give each construct a different name."),
            twice = .("'%s' is an indicator of more than one construct. In PLS-SEM each indicator belongs to one construct only; keep it in one of them."),
            unknown = .("'%s' appears in the structural model but is not defined as a construct with indicators."),
            self = .("'%s' cannot predict itself."),
            loop = .("The structural model has a loop (%s). PLS-SEM estimates recursive models only, in which no construct predicts itself through others: remove one path of the loop."),
            isolated = .("'%s' is not connected to any other construct. Drag it into the row of the construct it predicts, or drag its predictors into its row, or remove it."),
            hoc_no_name = .("A higher-order construct has no name. Give each higher-order construct a name."),
            hoc_clash = .("'%s' is the name of a first-order construct and of a higher-order construct. Use a different name for each."),
            hoc_two = .("The higher-order construct '%s' needs at least two lower-order constructs. Drag two or more first-order constructs into it."),
            hoc_unknown = .("'%s' in the higher-order construct '%s' is not a first-order construct with indicators."),
            hoc_twice = .("'%s' is a dimension of two higher-order constructs. Each lower-order construct can belong to one higher-order construct only."),
            hoc_plsc = .("Higher-order constructs are estimated with PLS in two stages; consistent PLS with higher-order constructs is not available in this version. Choose PLS as the estimator."),
            hoc_path_loc = .("'%s' is a dimension of the higher-order construct '%s', so it cannot have structural paths of its own. Draw the paths to or from '%s' instead."),
            hoc_interaction = .("The higher-order construct '%s' is part of an interaction. Interactions with higher-order constructs are not available in this version."),
            interaction_order = .("The interaction %s has more than two constructs. PLSsemLab estimates two-way interactions; build it from two constructs."),
            interaction_self = .("The interaction %s predicts %s, one of its own components. An interaction must predict a different construct."),
            interaction_main = .("The interaction %s predicts %s, but %s is not also a predictor of %s. Add the main effect of each component to the same construct: without it the interaction term mixes the moderation with the main effect and cannot be read as moderation."),
            not_numeric = .("'%s' is not numeric. Indicators must be numeric variables."),
            constant = .("'%s' has the same value for every case, so it carries no information. Remove it from its construct."),
            sentinel = .("'%s' has %d value(s) of %s, far outside the range of its other values (%s to %s). If this is a missing-data code, declare it as missing in jamovi's data view (Setup > Missing values) and run the analysis again."),
            ordinal_mean = .("Mean replacement cannot be used with ordinal indicators: the mean of an ordinal indicator is usually not one of its categories. Choose Exclude cases listwise in Missing values, or treat the indicators as continuous."),
            approach_plsc = .("Consistent estimation (PLSc) corrects PLS-PM weights for measurement error; with %s it is not defined (cSEM returns implausible estimates). Choose PLS as the estimator, or PLS-PM or GSCA as the weighting approach (with GSCA, consistent estimation is GSCAm; Hwang et al., 2017)."),
            approach_hoc = .("Higher-order constructs are estimated with the disjoint two-stage approach of PLS-SEM, defined for PLS-PM weights; with %s they are not available in this version. Choose PLS-PM as the weighting approach."),
            approach_gsca_nonlinear = .("cSEM does not estimate interaction terms with %s. Choose another weighting approach (PLS-PM is the usual one for moderation), or remove the interaction."),
            approach_pca_single = .("cSEM's %s weights fail with constructs measured by a single indicator (a principal component of one variable is the variable itself). Choose another weighting approach, or give every construct two or more indicators."),
            few_cases = .("Only %d cases have complete data on the indicators, too few to estimate the model. Check the missing values or use mean replacement."),
            estimation = .("cSEM could not estimate the model: %s")
        ),

        # Notices (Category B, never block).
        # ES: Avisos (Categoría B, nunca bloquean).
        notapply = list(
            na_hoc_reliability = .("Reliability of a higher-order construct applies to reflective higher-order constructs; the ones in this model are formative, and their quality is read from the weights and VIF of their dimensions in the table above."),
            na_hoc_htmt = .("There is no pair of a reflective higher-order construct and another reflective construct, so there is no higher-order HTMT to report."),
            na_htmt = .("HTMT compares reflective constructs in pairs and needs at least two; this model has %d."),
            na_loadings_plot = .("The loadings plot shows the indicators of reflective constructs, and this model has none."),
            na_htmt_plot = .("The HTMT plot needs at least two reflective constructs.")
        ),
        notices = list(
            mga_missing_group = .("%1$d case(s) without a value of %2$s were left out of the multigroup analysis."),
            mga_failed = .("The multigroup analysis could not be run: %s"),
            hoc_csem = .("Higher-order constructs (%s): cSEM's second-order routine (calculate2ndStage). It differs from the disjoint two-stage approach in three ways: in stage 1 the lower-order constructs also get structural paths among themselves; in stage 2 the other constructs are measured by their stage-1 scores instead of their own indicators; and in stage 2 a reflective higher-order construct is a common factor corrected by consistent PLS (cSEM sets .PLS_modes = NULL and .disattenuate = TRUE there), even when PLS was chosen. Choose the disjoint approach to follow Sarstedt et al. (2019) and Hair et al. (2021)."),
            hoc_two_stage = .("Higher-order constructs (%s): disjoint two-stage approach (Sarstedt et al., 2019). Stage 1 estimates every first-order construct, with each higher-order construct replaced in the structural model by its lower-order constructs; in stage 2 the stage-1 scores of the dimensions measure the higher-order construct, and every other construct keeps its own indicators. The measurement tables of first-order constructs come from stage 1; the structural model and the higher-order constructs from stage 2. With the bootstrap, both stages are resampled together."),
            rhoc_loadings = .("With an interaction in the model, cSEM cannot build the model-implied matrix used for \u03c1C, so \u03c1C is computed from the loadings, (\u03a3\u03bb)\u00b2 / ((\u03a3\u03bb)\u00b2 + \u03a3(1 \u2212 \u03bb\u00b2)); in models without interactions this gives the same value as cSEM."),
            empty_construct = .("'%s' has no indicators yet and was left out of the model."),
            fit_failed = .("The overall fit test could not be run: %s"),
            predict_failed = .("PLSpredict and CVPAT could not be run: %s"),
            predict_inadmissible_folds = .("%d of the cross-validation estimations were not admissible; their predictions were kept, as cSEM does when it is told to ignore inadmissible results. Read the prediction results with care."),
            single_reflective = .("'%s' has a single indicator: its loading is fixed at 1 and its measurement quality cannot be evaluated."),
            inadmissible = .("The estimates are not admissible (%s). Results are shown, but should not be interpreted until the cause is fixed: check indicators with very low or negative correlations, or very small samples."),
            dropped = .("%d case(s) with missing values were excluded; %d case(s) remain."),
            replaced = .("%d missing value(s) were replaced by the mean of their indicator (%d case(s) affected)."),
            negative_loadings = .("Reflective indicators with a negative loading: %s. They are almost certainly items worded in the opposite direction that were not recoded. Recode them in jamovi (for a scale from 1 to k, the new value is k + 1 minus the old one) and run the analysis again: until then, the reliability, AVE and HTMT of their constructs are distorted."),
            few_categories = .("Indicators with 5 categories or fewer are treated as continuous: %s. With so few categories Pearson correlations underestimate the relationships; consider Ordinal (polychoric correlations) in Estimation."),
            many_categories = .("Indicators with more than 10 categories are treated as ordinal: %s. Polychoric correlations are meant for a few ordered categories; with many categories, treating the indicators as continuous is usually adequate and more stable."),
            no_reflective_quality = .("The model has no reflective constructs, so reliability, convergent validity (AVE) and discriminant validity (HTMT) do not apply. Formative constructs are judged by the collinearity and the weights of their indicators."),
            one_reflective_htmt = .("Discriminant validity (HTMT) compares pairs of reflective constructs; the model has only one.")
        ),

        # Footnotes of cells that cannot be computed (Category B).
        # ES: Notas al pie de celdas que no se pueden calcular (Categoría B).
        footnotes = list(
            mga_hoc = .("Not computable in this version for models with higher-order constructs: both stages would have to be repeated in every group and in every permutation."),
            mga_group_indicator = .("Not computable: the grouping variable %s is also an indicator of the model. Choose a variable that is not in the model."),
            mga_one_group = .("Not computable: the grouping variable %s has fewer than two groups with cases."),
            mga_many_groups = .("Not computable: the grouping variable %1$s has %2$d groups, and this module compares at most %3$d (with more, the pairwise comparisons multiply and each group gets small). Merge categories or choose another variable."),
            mga_small_group = .("Not computable: %1$s. Each group needs at least %2$d cases (a minimum of this module) to estimate the model on its own; merge small categories or collect more data."),
            mga_inadmissible = .("Not computable: the estimates are not admissible in %s (see the Groups table). Fix the cause first."),
            mga_error = .("Not computable: cSEM stopped with: %s"),
            micom_plsc = .("Not computable with consistent PLS: MICOM is defined for composites (Henseler, Ringle & Sarstedt, 2016), and PLSc treats the reflective constructs as common factors. Choose PLS in the Estimation box to test the invariance of the composites; for common factors, invariance is usually tested with a multigroup CFA."),
            micom_ordinal = .("Not computable with ordinal indicators: cSEM's testMICOM() builds the scores from the raw category codes and stops. The path differences are still computed."),
            micom_error = .("Not computable: cSEM's testMICOM() stopped with: %s"),
            single_reliability = .("A single indicator has no internal consistency to estimate: its reliability and AVE are 1 by definition."),
            single_vif = .("A construct with a single indicator has no collinearity among its indicators."),
            ordinal_note = .("Computed from polychoric correlations (ordinal indicators): the values refer to the reliability of the latent continuous responses assumed behind the categories, not to the observed sum score, which is usually lower (Chalmers, 2018, see references)."),
            omega_two = .("A one-factor model with two indicators is not identified, so \u03c9 cannot be estimated; with two indicators, alpha (Spearman-Brown) is the usual reliability estimate."),
            omega_nonconverged = .("The one-factor CFA did not converge, so \u03c9 cannot be estimated."),
            omega_heywood = .("The one-factor CFA gave a standardized loading of 1 or more (a Heywood case), so \u03c9 is not reported."),
            hoc_htmt_csem = .("Not computable: cSEM's second-order routine measures the other constructs by a single score in stage 2, so their HTMT with the higher-order construct is not defined. Choose the disjoint approach to assess it."),
            htmt_single = .("%s has a single indicator: cSEM takes its within-construct correlation as 1 (perfect reliability), so this HTMT is a lower bound of the overlap between the two constructs."),
            htmt_signs = .("Not computable: the indicators of these constructs correlate with mixed signs. Check for reverse-coded items and recode them before the analysis."),
            fit_nonlinear = .("Not computable: with an interaction term the model implies no indicator correlation matrix, so the discrepancies of the overall fit test are not defined (cSEM; Dijkstra & Henseler, 2015)."),
            ipma_plsc = .("Not computable with consistent PLS: the IPMA needs composite scores (Ringle & Sarstedt, 2016), and PLSc treats the reflective constructs as common factors. Choose PLS in the Estimation box."),
            ipma_nonlinear = .("Not computable: with an interaction term the total effects are not constant, so the importance of a construct is not a single number."),
            ipma_hoc = .("Not computable in this version for models with higher-order constructs."),
            ipma_range = .("Not computable: the maximum of the scale must be larger than its minimum."),
            ipma_error = .("Not computable: cSEM's doIPMA() stopped with: %s"),
            ipma_no_boot = .("Without the bootstrap the importance values are not tested: a construct can look important with a total effect that does not differ from 0. Run the bootstrap before deciding priorities."),
            ipma_ns = .("Rows marked \u201ctotal effect not significant\u201d have a total effect whose bootstrap interval includes 0: their importance cannot be told apart from none, so they should not set priorities."),
            predict_small_sample = .("Small sample for the cross-validation: %d cases, %d per held-out fold and %d per training set for %d predictors of LM. With fewer than 20 cases per fold or fewer than 10 training cases per predictor of LM (rules of thumb of this module) the metrics vary from one set of folds to another and CVPAT has little power: read the results as indicative, use fewer folds or more repetitions, or collect more data."),
            ipma_negative = .("Some indicator weights are negative, so the performance of their constructs can fall outside 0-100 and their meaning is unclear (Ringle & Sarstedt, 2016). Check those indicators before using the map."),
            nca_plsc = .("Not computable with consistent PLS: the NCA uses the composite scores of the IPMA (Richter et al., 2020, see references), and PLSc treats the reflective constructs as common factors. Choose PLS in the Estimation box."),
            nca_nonlinear = .("Not computable: with an interaction term the scores of the IPMA, on which the NCA works, are not defined in this version."),
            nca_hoc = .("Not computable in this version for models with higher-order constructs."),
            nca_error = .("Not computable: the necessary condition analysis stopped with: %s"),
            nca_negative_slope = .("The CR-FDH line through the peers has a negative slope: there is no ceiling in the upper-left corner, so its effect size is not defined (the permutations that give such a line are left out of the test)."),
            nca_note = .("Scores: unstandardized construct scores rescaled to 0-100 with a scale range of %s to %s (%s), as in the IPMA. d: ceiling zone / scope (Dul, 2016); 0.1 to 0.3 medium, 0.3 to 0.5 large, 0.5 or more very large. p: permutation test with %d permutations, seed %d (Dul, van der Laan & Kuik, 2020). A condition is read as necessary when d \u2265 0.1 and p < .05. Accuracy: percentage of cases on or below the ceiling line (CE-FDH is 100%% by construction)."),
            nca_combined_note = .("NCA d and p: the %s ceiling. Path significant: the bootstrap interval of the path coefficient excludes 0. Must-have: a necessary condition; should-have: a construct whose higher levels raise the outcome on average (Richter et al., 2020)."),
            nca_no_boot = .("Without the bootstrap the paths are not tested: the reading uses only the NCA. Run the bootstrap to complete the combined reading."),
            nca_bn_note = .("Each cell is the minimum level of the condition (percentage of its range) needed for the level of the outcome in the row (percentage of its range). NN: not necessary at that level. NA: the ceiling line asks for more than the highest observed level of the condition."),
            mgcfa_none = .("Not computable: no reflective construct has two or more indicators, and a common factor with one indicator is not identified."),
            mgcfa_ordinal = .("Not computable in this version with ordinal indicators (the categorical MGCFA, with thresholds, is planned)."),
            mgcfa_error = .("Not computable: lavaan stopped with: %s"),
            mgcfa_note = .("Multigroup CFA of the reflective constructs with lavaan (%s), %d groups, correlated factors. Each model adds equality constraints to the previous one: metric, equal loadings; scalar, equal loadings and intercepts. Configural: good fit with CFI \u2265 .95 and SRMR \u2264 .08, acceptable with CFI \u2265 .90 and SRMR \u2264 .10 (Hu & Bentler, 1999); RMSEA is shown but not used, because with few degrees of freedom it overstates misfit (Kenny, Kaniskan & McCoach, 2015). Metric and scalar are supported when CFI drops by no more than .010 and RMSEA rises by no more than .015 (SRMR by no more than .030 for metric and .010 for scalar; Chen, 2007). The chi-square difference is shown too, but with large samples it flags trivial differences (Cheung & Rensvold, 2002)."),
            mgcfa_rmsea_cell = .("RMSEA = %s, above .08, would call the configural fit poor, but with %s degrees of freedom RMSEA overstates misfit (Kenny, Kaniskan & McCoach, 2015): the configural decision uses CFI and SRMR."),
            mgcfa_left = .("Left out of the CFA: %s (formative constructs or reflective constructs with one indicator)."),
            mgcfa_nonconv = .("lavaan did not converge for: %s. Do not interpret those rows."),
            mgcfa_warnings = .("lavaan warned: %s"),
            predict_nonlinear = .("Not computable: cSEM predicts only from linear models, and this model has an interaction term."),
            predict_hoc = .("Not computable in this version for models with higher-order constructs: the prediction would have to repeat both stages in every fold."),
            predict_inadmissible = .("Not computable: the estimates are not admissible (see the notice). Fix the cause first."),
            cvpat_alt_empty = .("Not computable: the competing model would have no structural paths left."),
            cvpat_alt_error = .("Not computable: the competing model could not be estimated: %s"),
            cvpat_alt_inadmissible = .("Not computable: the estimates of the competing model are not admissible."),
            predict_small = .("Not computable: there are more folds than cases."),
            predict_error = .("Not computable: the cross-validation stopped with: %s"),
            med_interaction = .("The model has interaction terms: chains through them (conditional indirect effects, moderated mediation) are not listed in this version."),
            fit_hoc = .("Not computable in this version for models with higher-order constructs: the test would assess only stage 2, where the dimensions enter as fixed scores, and its reference distribution would ignore stage 1."),
            fit_inadmissible = .("Not computable: the estimates are not admissible (see the notice). A fit test of an inadmissible solution has no meaning; fix the cause first."),
            fit_error = .("Not computable: cSEM's testOMF() stopped with: %s"),
            failed = .("Not computable: %s"),
            rho_a_pls = .("\u03c1A comes from a consistent PLS estimation of the same model (same weights): it is the reliability that consistent PLS uses to correct for measurement error (Dijkstra & Henseler, 2015, see references)."),
            rho_a_approach = .("\u03c1A is defined for PLS-PM weights (Dijkstra & Henseler, 2015, see references); with %s it is not computed. Read Cronbach's \u03b1 and \u03c1C, which bound reliability from below and from above."),
            ipma_approach = .("Not computable with this weighting approach: cSEM computes the importance-performance map only with PLS-PM weights. Choose PLS-PM in the Estimation box."),
            nca_approach = .("Not computable with this weighting approach: the NCA uses the scores of the IPMA, which cSEM defines only with PLS-PM weights. Choose PLS-PM in the Estimation box."),
            mga_maxvar = .("Not computable with MAXVAR: its weights are fixed only up to a common sign, which can differ between groups, so MICOM and the path differences would compare composites of opposite sign. Choose another weighting approach (the multigroup CFA does not depend on it)."),
            mardia_note = .("Mardia (1970): multivariate skewness b1 (statistic n b1 / 6, chi-square) and kurtosis b2 (statistic z; expected value under normality p(p + 2) = %3$d) of the %1$d indicators, n = %2$d. PLS-SEM does not assume normality and its percentile bootstrap does not need it; the measures matter for maximum-likelihood steps such as the multigroup CFA and for judging skewed bootstrap distributions (Cain et al., 2017)."),
            mardia_singular = .("Not computable: the covariance matrix of the indicators is singular (an indicator is a linear combination of others)."),
            bench_same = .("The extra benchmark is the weighting approach of the model itself; choose a different one to compare."),
            bench_error = .("Not computable: the model could not be estimated with the extra benchmark's weighting approach: %s"),
            bench_note = .("Extra benchmark: the same model estimated with %s weights, cross-validated on the same folds as the model; in CVPAT the test against it is two-sided, as against a competing model."),
            compare_hoc = .("Not computable in this version for models with higher-order constructs."),
            compare_nodrop = .("Choose, in the Prediction box, the paths left out of the competing model: the comparison needs two different models."),
            compare_error = .("Not computable: the comparison stopped with: %s"),
            compare_srmr = .("SRMR is not computed for one of the models (cSEM cannot build the model-implied correlations with an interaction term)."),
            compare_note = .("Competing model: the main model without %s, estimated with the same data and settings. An outcome whose equation keeps all its predictors changes only slightly, through the weights. R\u00b2 and adjusted R\u00b2: higher is better; AIC, AICu, BIC, GM and HQ of each structural equation: lower is better; SRMR: lower is better. Sharma et al. (2019, 2021) found BIC and GM the most reliable for choosing among PLS-SEM models; R\u00b2 always favors the model with more paths."),
            compare_paths_note = .("\u2014: the path is left out of the competing model. A path that changes markedly when another is removed signals overlap between the predictors."),
            alpha_negative = .("A negative alpha means that some indicators of the construct correlate negatively: check for reverse-coded items."),
            fl_note = .("Diagonal: square root of the AVE. Below the diagonal: correlations between constructs. Discriminant validity holds for a pair when both square roots exceed their correlation."),
            fl_fails = .("The correlation with %s exceeds the square root of the AVE of one of the two constructs.")
        ),

        # Bootstrap status and table notes.
        # ES: Estado del bootstrap y notas de las tablas.
        boot = list(
            micom_note = .("Step 1 (configural invariance) holds by construction: every group uses the same indicators, the same data treatment and the same algorithm settings. Step 2: c is the correlation between the scores built with the weights of each group; compositional invariance holds when c is not significantly below 1 (one-sided permutation p of .05 or more, that is, c above the 5%% quantile of its permutation distribution). Step 3: difference of the means and log of the ratio of the variances of the standardized pooled scores (first group minus second), with two-sided permutation p. %1$d permutations (%2$d admissible), seed %3$d, %4$d s."),
            micom_invariance_note = .("Invariance: None, step 2 fails and the construct cannot be compared across these groups; Partial, step 2 holds and the paths can be compared; Full, step 3 also holds and the groups could be pooled (Henseler, Ringle & Sarstedt, 2016)."),
            micom_single = .("Single indicator (%s): c = 1 by definition, so compositional invariance holds trivially."),
            mgd_note = .("Difference = first group minus second group. Permutation test (Chin & Dibbern, 2010): %1$d permutations (%2$d admissible). PLS-MGA (Henseler et al., 2009): %3$d bootstrap resamples per group. cSEM returns P(first \u2264 second), a one-sided value: near 0 the path is larger in the first group, near 1 in the second. The two-sided p = 2 \u00d7 min(P, 1 \u2212 P) is used for the decision, at .05 for both tests. Seed %4$d, %5$d s."),
            mgd_smartpls = .("SmartPLS reads PLS-MGA as significant when P < .05 or P > .95, which amounts to a two-sided level of .10; near those limits the two programs can disagree."),
            mgd_adjust = .("The p values of both tests are corrected for %1$d comparisons (%2$s method), over every path and pair of groups. P(first \u2264 second) is shown uncorrected."),
            mgd_micom_fail = .("Compositional invariance was not established (MICOM step 2) for %s: a difference in a path that involves these constructs may come from the constructs meaning something different in each group, not from a different relationship."),
            mga_groups_note = .("Each group is estimated on its own, with the settings of the Estimation box."),
            running = .("Bootstrap running: %d of %d resamples done. Changing any option stops it."),
            fit_note = .("Critical value: the %5$s%% quantile of the bootstrap distribution of each discrepancy under exact fit (%1$d resamples; %2$d admissible for the estimated model, %3$d for the saturated one; seed %4$d is the bootstrap seed; %6$d s). p (bootstrap): (number of admissible resamples at least as large as the observed value + 1) / (admissible resamples + 1), so it is never 0."),
            predict_note = .("%1$d-fold cross-validation repeated %2$d times (folds drawn by cSEM with seeds %3$d, %3$d + 1, ...; %4$d s). Each case is predicted by a model estimated without it; results are averages over the repetitions."),
            ipma_note = .("Importance: unstandardized total effect on the target (the change in the target, on its scale, when the construct rises by one point). Performance: mean of the construct's unstandardized scores rescaled to 0-100 with a scale range of %s to %s (%s)."),
            cvpat_alt_note = .("Competing model: your model without %s, estimated on the same folds. Against it the test is two-sided (Liengaard et al., 2021): a negative difference favors your model, a positive one the competing model."),
            predict_metric_note = .("Metric: the comparison of PLS with LM uses the RMSE, or the MAE when the prediction errors of PLS are clearly asymmetric (|skewness| > 1, a rule of thumb of this module), as Shmueli et al. (2019) recommend."),
            q2_not_blindfolding = .("Q²predict is not the Stone-Geisser Q² of blindfolding: that one omits data points and predicts them from the same sample (in-sample), while Q²predict predicts cases left out of the estimation (out-of-sample)."),
            cvpat_note = .("Loss: squared prediction error of each case, averaged over the indicators and the repetitions. Loss difference = PLS loss - benchmark loss (negative: PLS predicts better). One-sided paired t test (H1: PLS predicts better); PLS predicts better when p < .05 and the difference is negative."),
            med_note = .("Indirect: product of the path coefficients of the chain. Interval: %s%% percentile bootstrap interval of that product, computed from the same resamples as the paths. The type of mediation follows Zhao et al. (2010): an effect is significant when its interval excludes 0."),
            fit_same = .("Your structural model already relates every pair of constructs, so the estimated and the saturated model are the same model and both tests coincide."),
            time_note = .("Elapsed time of this run: {seconds} s. It changes from one run to another and is not part of the result."),
            jk_summary_note = .("Jackknife: one estimation per case left out, so the number of estimations is the sample size and no seed is needed."),
            not_done = .("The bootstrap could not be completed; see the notice at the top of the results."),
            cached_note = .("Results reused from an earlier run with the same model, data and bootstrap options; Seconds is the time of that run."),
            failed = .("The bootstrap could not be computed, so the tables show estimates without intervals: %s"),
            some_failed = .("Some bootstrap blocks failed and were left out: %s"),
            ci_note = .("Intervals: %s%% percentile bootstrap intervals from %d admissible resamples."),
            ci_note_jk = .("Intervals: %s%% jackknife t intervals (estimate \u00b1 t \u00d7 jackknife standard error) from %d admissible leave-one-out estimations."),
            p_note_jk = .("p values: t = estimate / jackknife standard error, with n - 1 degrees of freedom."),
            med_note_jk = .("Indirect: product of the path coefficients of the chain. Interval: %s%% jackknife t interval of that product, from the same leave-one-out estimations as the paths. The type of mediation follows Zhao et al. (2010): an effect is significant when its interval excludes 0."),
            p_ci_disagree = .("The p value and the percentile interval disagree for this path (a borderline case). The decision follows the interval, as recommended for PLS-SEM (Hair et al., 2019, see references); report both, and check with more resamples or another seed."),
            p_note = .("p values come from cSEM: t = estimate / bootstrap standard error."),
            htmt_note = .("Upper bound: the one-sided 95%% bootstrap upper bound (the 95th percentile of %d admissible resamples). Discriminant validity holds when it stays below the threshold (Henseler et al., 2015, see references)."),
            htmt_note_jk = .("Upper bound: the one-sided 95%% jackknife upper bound (estimate + t \u00d7 jackknife standard error, from %d admissible leave-one-out estimations). Discriminant validity holds when it stays below the threshold (Henseler et al., 2015, see references).")
        ),

