            fit_srmr_low_reject = .("The SRMR is below the descriptive 0.08 rule while the test rejects exact fit. This is frequent: the test detects any departure, however small, and its power grows with the sample. Report both, and judge whether the size of the misfit matters for your conclusions."),
            hoc_loadings_ok = .("%s: every dimension loads 0.708 or more on it (%s)."),
